<style>
    :root{font-family:Inter,ui-sans-serif,system-ui,sans-serif;color:#17211b;background:#f4f7f3}*{box-sizing:border-box}body{margin:0}.shell{display:flex;min-height:100vh}.sidebar{width:248px;background:#123c2a;color:#dce9e0;padding:28px 18px}.logo{font:700 22px Georgia,serif;color:#fff;margin:0 12px 42px;line-height:1.25;word-break:break-word}.nav-label{font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:#93b5a1;margin:23px 12px 8px}.nav a{display:block;padding:11px 12px;border-radius:8px;color:#c9ded0;text-decoration:none;font-size:14px;margin:3px 0}.nav a.active,.nav a:hover{color:#fff;background:#255a42}.main{flex:1;min-width:0}.topbar{height:76px;background:#fff;border-bottom:1px solid #e3e9e3;display:flex;align-items:center;justify-content:space-between;padding:0 42px}.crumb{font-size:14px;color:#718077}.crumb strong{color:#183b2a}.profile{display:flex;align-items:center;gap:11px;font-size:13px}.avatar{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:#e9c27d;color:#6d4d1c;font-weight:700}.content{max-width:1320px;padding:36px 42px}.heading{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:28px;gap:16px}.eyebrow{font-size:12px;color:#6c7c72;text-transform:uppercase;letter-spacing:.1em}.heading h1{margin:5px 0 7px;font:600 32px Georgia,serif;color:#143b2a}.heading p{margin:0;color:#748078;font-size:14px}.button{border:0;border-radius:7px;padding:12px 17px;background:#e5a83c;color:#fff;font-weight:700;cursor:pointer;text-decoration:none;display:inline-block}.button:hover{background:#d49428}.button.ghost{background:#fff;color:#255a42;border:1px solid #c9dbcf}.button.small{padding:8px 12px;font-size:12px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.module-cards{margin-top:16px}.card,.panel{background:#fff;border:1px solid #e4ebe5;border-radius:10px;box-shadow:0 3px 12px #183b2a08}.card{padding:19px}.card-label{font-size:12px;color:#77837b}.card-value{font-size:24px;font-weight:700;margin:11px 0 7px;color:#173c2b}.positive{color:#2a8b61;font-size:12px}.muted{color:#8a968f;font-size:12px}.grid{display:grid;grid-template-columns:1.35fr .9fr;gap:18px;margin-top:18px}.panel{padding:23px}.panel-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;gap:12px}.panel h2{font:600 19px Georgia,serif;margin:0;color:#173c2b}.panel-link{font-size:12px;color:#b1791e;text-decoration:none}.bars{height:200px;display:flex;align-items:end;gap:15px;border-bottom:1px solid #e5ebe6;padding:0 14px}.bar-col{height:100%;flex:1;display:flex;flex-direction:column;justify-content:end;align-items:center;gap:8px}.bar{width:100%;max-width:34px;border-radius:5px 5px 0 0;background:#75aa89}.bar.highlight{background:#e5aa40}.month{font-size:11px;color:#89958d}.donut-row{display:flex;align-items:center;gap:25px}.donut{width:150px;height:150px;border-radius:50%;background:conic-gradient(#266c4b 0 42%,#e5aa40 42% 68%,#96c5a6 68% 84%,#dce9df 84%);position:relative}.donut:after{content:'';position:absolute;inset:34px;border-radius:50%;background:#fff}.legend{flex:1}.legend div{display:flex;align-items:center;gap:8px;font-size:13px;margin:13px 0;color:#5d6b62}.dot{width:9px;height:9px;border-radius:50%;background:#266c4b}.dot.gold{background:#e5aa40}.dot.light{background:#96c5a6}.table-wrap{margin-top:18px}.table{width:100%;border-collapse:collapse;font-size:13px}.table th{text-align:left;color:#8a958e;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.04em;padding:12px 10px;border-bottom:1px solid #e8eee9}.table td{padding:15px 10px;border-bottom:1px solid #eef2ef;vertical-align:middle}.table td.num,.table th.num{text-align:right}.tag{font-size:11px;padding:4px 7px;border-radius:5px;background:#e5f2e9;color:#2d7750;white-space:nowrap}.tag.draft{background:#eef1ef;color:#6a756f}.tag.sent,.tag.received{background:#e5f2e9;color:#2d7750}.tag.partial{background:#fff1d9;color:#96681e}.tag.paid{background:#dcecff;color:#2